css:
.curarch-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2e2a23;
    background: linear-gradient(170deg, #faf6ee 0%, #f3ece0 60%, #ece2d2 100%);
    border-radius: 18px;
    border: 1px solid #e3d8c4;
}

.curarch-container * {
    box-sizing: border-box;
}

.curarch-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f3d35 0%, #14534633 100%), linear-gradient(135deg, #0f3d35 0%, #1c6356 60%, #2a7d6b 100%);
    color: #f6efe0;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #0c322c;
    box-shadow: 0 12px 30px rgba(15, 61, 53, 0.28);
}

.curarch-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #fdf8ec;
    font-family: Georgia, 'Times New Roman', serif;
}

.curarch-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0c873;
    background: rgba(240, 200, 115, 0.14);
    border: 1px solid rgba(240, 200, 115, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.curarch-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dfe9e2;
}

.curarch-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #6b6253;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.curarch-period-counter #currentDay,
.curarch-period-counter #maxPeriods {
    font-weight: 800;
    color: #1c6356;
}

.curarch-round-name {
    background: rgba(28, 99, 86, 0.12);
    color: #1c6356;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.curarch-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a6a12;
    background: rgba(240, 200, 115, 0.22);
    border: 1px solid rgba(176, 130, 30, 0.35);
    padding: 4px 12px;
    border-radius: 999px;
}

.curarch-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.curarch-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e6dcc8;
    box-shadow: 0 6px 16px rgba(46, 42, 35, 0.08);
    border-top: 4px solid #1c6356;
}

.curarch-card-coverage { border-top-color: #1c6356; }
.curarch-card-util { border-top-color: #3f7cac; }
.curarch-card-sat { border-top-color: #c8862b; }
.curarch-card-accred { border-top-color: #7a5aa6; }

.curarch-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7f6c;
}

.curarch-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1c2a26;
    font-variant-numeric: tabular-nums;
    font-family: Georgia, 'Times New Roman', serif;
}

.curarch-card-coverage .curarch-value { color: #16574b; }
.curarch-card-util .curarch-value { color: #2f6790; }
.curarch-card-sat .curarch-value { color: #b0741f; }
.curarch-card-accred .curarch-value { color: #654a8e; }

.curarch-sublabel {
    font-size: 0.75rem;
    color: #8a7f6c;
    line-height: 1.35;
}

.curarch-coverage-low .curarch-value { color: #c0392b; }
.curarch-coverage-high .curarch-value { color: #16574b; }
.curarch-accred-low { border-top-color: #c0392b; }
.curarch-accred-low .curarch-value { color: #c0392b; }
.curarch-accred-high { border-top-color: #1c6356; }
.curarch-util-low .curarch-value { color: #c0392b; }

.curarch-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f3d35;
    border: 1px solid #0c322c;
    color: #eadfca;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.curarch-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0c873;
}

.curarch-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #c8862b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(46, 42, 35, 0.07);
}

.curarch-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.curarch-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14463c;
    margin-bottom: 6px;
    font-family: Georgia, 'Times New Roman', serif;
}

.curarch-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #463f33;
}

.curarch-briefing-text strong { color: #16574b; }
.curarch-briefing-text em { color: #9a6a12; font-style: italic; }

.curarch-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e6dcc8;
    box-shadow: 0 6px 16px rgba(46, 42, 35, 0.07);
}

.curarch-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14463c;
    border-bottom: 2px solid #ece2d2;
    padding-bottom: 8px;
    font-family: Georgia, 'Times New Roman', serif;
}

.curarch-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a352c;
    margin: 14px 0 6px;
}

.curarch-container select,
.curarch-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d6c9b1;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fcf8f0;
    color: #2e2a23;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.curarch-container select:focus,
.curarch-container input[type="number"]:focus {
    outline: none;
    border-color: #1c6356;
    box-shadow: 0 0 0 3px rgba(28, 99, 86, 0.16);
}

.curarch-container select option {
    background-color: #fcf8f0;
    color: #2e2a23;
}

.curarch-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1c6356;
}

.curarch-range-readout,
.curarch-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b6253;
    margin-top: 4px;
}

.curarch-range-readout span:nth-child(2),
.curarch-alloc-readout span:nth-child(2) {
    color: #1c6356;
    font-weight: 800;
}

.curarch-hint {
    font-size: 0.8rem;
    color: #8a7f6c;
    margin-top: 4px;
    line-height: 1.4;
}

.curarch-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.curarch-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6efe1;
    border: 1px solid #e0d4bd;
    border-radius: 9px;
    padding: 8px 12px;
}

.curarch-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a352c;
}

.curarch-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.curarch-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.curarch-container .btn-primary {
    background: linear-gradient(135deg, #0f3d35 0%, #1c6356 60%, #2a7d6b 100%);
    border: none;
    color: #fdf8ec;
    padding: 11px 28px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(15, 61, 53, 0.30);
}

.curarch-container .btn-primary:hover {
    filter: brightness(1.08);
}

.curarch-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d6c9b1;
    color: #6b6253;
    background: transparent;
}

.curarch-coach {
    background: linear-gradient(160deg, #163f37 0%, #1c4f44 100%);
    color: #e9e0cd;
    border: 1px solid #0c322c;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(15, 61, 53, 0.22);
}

.curarch-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0c873;
    margin-bottom: 8px;
}

.curarch-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.curarch-coach-body strong { color: #f0c873; }
.curarch-coach-body em { color: #e9e0cd; font-style: italic; }

.curarch-history,
.curarch-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e6dcc8;
    box-shadow: 0 6px 16px rgba(46, 42, 35, 0.07);
}

.curarch-history h3,
.curarch-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14463c;
    font-family: Georgia, 'Times New Roman', serif;
}

.curarch-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a352c;
}

.curarch-container table#usfHistoryTable th {
    background: #0f3d35;
    color: #f0c873;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #0c322c;
}

.curarch-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece2d2;
    color: #463f33;
}

.curarch-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8f2e7;
}

.curarch-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .curarch-container {
        padding: 14px;
    }
    .curarch-header h1 {
        font-size: 1.7rem;
    }
    .curarch-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .curarch-value {
        font-size: 2rem;
    }
    .curarch-clock {
        margin-left: 0;
    }
    .curarch-period-counter {
        font-size: 0.88rem;
    }
    .curarch-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .curarch-alloc-row {
        flex-wrap: wrap;
    }
    .curarch-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .curarch-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion scorecard (append-only, namespaced .cua-cm-*) */
.cua-cm { margin-top: 8px; }
.cua-cm-incomplete { text-align: center; color: #0f3d35; font-size: 1rem; padding: 18px; }
.cua-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.cua-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #0c322c 0%, #1c6356 55%, #f0c873 150%); color: #fffdf8; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(12,50,44,0.28); }
.cua-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.cua-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.cua-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0c873; }
.cua-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fffdf8; border: 1px solid #dcecdf; border-radius: 14px; padding: 14px 20px; }
.cua-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #6f9188; }
.cua-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; color: #0f3d35; margin-top: 4px; line-height: 1.15; }
.cua-cm-section { margin-bottom: 16px; }
.cua-cm-section-h { font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.6px; font-weight: 700; color: #1c6356; margin-bottom: 8px; border-bottom: 1px solid #dcecdf; padding-bottom: 4px; }
.cua-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.cua-cm-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; font-size: 0.85rem; font-weight: 600; border: 1px solid transparent; }
.cua-cm-ok { background: #e3f2ec; color: #0f3d35; border-color: #bfe0d1; }
.cua-cm-no { background: #f7e5e2; color: #a3382c; border-color: #eec3bc; }
.cua-cm-ico { font-weight: 800; }
.cua-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
.cua-cm-kpi { background: #fdfdfa; border: 1px solid #dcecdf; border-radius: 12px; padding: 12px 10px; text-align: center; }
.cua-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #1c6356; line-height: 1; }
.cua-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #244; margin-top: 6px; }
.cua-cm-kpi-sub { font-size: 0.68rem; color: #6f9188; margin-top: 2px; }
.cua-cm-insights { margin: 0; padding-left: 20px; color: #14312b; }
.cua-cm-insights li { margin-bottom: 6px; line-height: 1.4; }
@media (max-width: 620px) { .cua-cm-kpis { grid-template-columns: repeat(2, 1fr); } }

