(function() {
    'use strict';

    class CurriculumArchitectAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Curriculum Architect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (ICAD / Leading Enterprise Transformation).
            this.HOURS_CAP = 96;        // 12 days x 8h contact-hours envelope
            this.SCOPED_HOURS = 140;    // initial scope; 44h must be cut
            this.OUTCOMES = 6;          // contractually required learning outcomes
            this.FACULTY_FREE = 9;      // of 28 core faculty free in the window
            this.PARTICIPANTS = 35;     // client directors in the cohort
            this.AT_RISK_FEE = 20;      // % of fee tied to outcome assessment

            // Concept truths the math rewards.
            this.TRUE_FRAME = `system`;
            this.TRUE_SEQUENCE = `arc`;
            this.TRUE_ASSESS = `prepost`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    coverage: 17,        // % of 6 outcomes covered & assessed (~1/6 at start)
                    util: 50,            // faculty utilization sustainability (100 = healthy)
                    sat: 50,             // projected participant satisfaction (0-100)
                    accred: 20,          // assurance-of-learning audit readiness (0-100)
                    hoursUsed: 0,        // contact hours committed (metered in R2)
                    overCap: false,      // blew the 96h envelope
                    overloaded: false,   // strip-mined the two star professors
                    taughtNotAssessed: false, // outcomes taught but never measured
                    coverageHistory: [17],
                    utilHistory: [50],
                    satHistory: [50],
                    accredHistory: [20],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Deliberately middling / wrong-leaning defaults — a blind click-through must not auto-win.
                state.decisions = {
                    frame: `content`,
                    gap: `finance`,
                    hours: `squeeze`,
                    foundations: 24,
                    application: 24,
                    integration: 24,
                    personal: 24,
                    sequence: `playlist`,
                    spacing: `none`,
                    mix: 50,
                    star: `overload`,
                    assess: `project`,
                    assessed: 3,
                    pitch: `coverage`,
                    probe: `taught`,
                    kpi: `sat_util`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const gp = document.getElementById(`gapInput`);
                const hr = document.getElementById(`hoursInput`);
                if (fr) decisions.frame = fr.value;
                if (gp) decisions.gap = gp.value;
                if (hr) decisions.hours = hr.value;
            } else if (round === 2) {
                const fo = document.getElementById(`foundationsInput`);
                const ap = document.getElementById(`applicationInput`);
                const it = document.getElementById(`integrationInput`);
                const pe = document.getElementById(`personalInput`);
                const sq = document.getElementById(`sequenceInput`);
                const sp = document.getElementById(`spacingInput`);
                if (fo) decisions.foundations = parseFloat(fo.value);
                if (ap) decisions.application = parseFloat(ap.value);
                if (it) decisions.integration = parseFloat(it.value);
                if (pe) decisions.personal = parseFloat(pe.value);
                if (sq) decisions.sequence = sq.value;
                if (sp) decisions.spacing = sp.value;
                const parts = [decisions.foundations, decisions.application, decisions.integration, decisions.personal];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(decisions.foundations + decisions.application + decisions.integration + decisions.personal);
                if (total !== this.HOURS_CAP) {
                    warn(`warn_hours_total`); return false;
                }
            } else if (round === 3) {
                const mx = document.getElementById(`mixInput`);
                const st = document.getElementById(`starInput`);
                const as = document.getElementById(`assessInput`);
                const ac = document.getElementById(`assessedInput`);
                if (mx) decisions.mix = parseInt(mx.value, 10);
                if (st) decisions.star = st.value;
                if (as) decisions.assess = as.value;
                if (ac) decisions.assessed = parseInt(ac.value, 10);
                if (!Number.isFinite(decisions.mix) || decisions.mix < 0 || decisions.mix > 100) {
                    warn(`warn_mix_range`); return false;
                }
                if (!Number.isFinite(decisions.assessed) || decisions.assessed < 0 || decisions.assessed > this.OUTCOMES) {
                    warn(`warn_assessed_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const pr = document.getElementById(`probeInput`);
                const kp = document.getElementById(`kpiInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (pr) decisions.probe = pr.value;
                if (kp) decisions.kpi = kp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite (was computed only in getPerformanceSummary and discarded).
            const coverage = Math.round(ds.coverage);
            const util = Math.round(ds.util);
            const sat = Math.round(ds.sat);
            const accred = Math.round(ds.accred);
            return Math.round(coverage * 0.30 + accred * 0.30 + sat * 0.22 + util * 0.18);
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let coverageDelta = 0, utilDelta = 0, satDelta = 0, accredDelta = 0, hoursSpent = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the brief as ONE joint constraint (Common Error: reading it as a single-axis problem).
                switch (d.frame) {
                    case `system`: coverageDelta += 8; accredDelta += 10; utilDelta += 3; coachKey = `coach_r1_system`; break;
                    case `content`: coverageDelta += 3; accredDelta -= 3; coachKey = `coach_r1_content`; break;
                    case `hours`: satDelta -= 3; accredDelta -= 5; coachKey = `coach_r1_hours`; break;
                    case `audit`: accredDelta -= 6; satDelta -= 2; coachKey = `coach_r1_audit`; break;
                }

                // Read the coverage matrix — change-leadership is the real gap (stars committed).
                switch (d.gap) {
                    case `change`: coverageDelta += 8; accredDelta += 5; if (d.frame === `system`) coachKey = `coach_r1_sharp`; break;
                    case `finance`: coverageDelta -= 2; coachKey = `coach_r1_finance`; break;
                    case `strategy`: coverageDelta -= 2; break;
                    case `none`: coverageDelta -= 6; accredDelta -= 4; coachKey = `coach_r1_nogap`; break;
                }

                // Confirm the hours math against the 96h cap (44h over).
                switch (d.hours) {
                    case `cut`: accredDelta += 6; utilDelta += 4; satDelta += 2; break;
                    case `squeeze`: satDelta -= 6; accredDelta -= 4; coachKey = `coach_r1_squeeze`; break;
                    case `ask`: satDelta -= 2; utilDelta -= 2; break;
                    case `ignore`: accredDelta -= 4; coachKey = `coach_r1_ignorehours`; break;
                }

                summaryKey = (d.frame === `system` && d.gap === `change` && d.hours === `cut`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Sequence & select within 96h (Common Errors: coverage over capacity; playlist not arc).
                const fo = d.foundations, ap = d.application, it = d.integration, pe = d.personal;
                hoursSpent = fo + ap + it + pe;

                // Balance across the four blocks: a coherent arc needs every block non-trivially funded,
                // with foundations and integration carrying weight.
                const blocks = [fo, ap, it, pe];
                const minBlock = Math.min.apply(null, blocks);
                const maxBlock = Math.max.apply(null, blocks);
                if (minBlock <= 8) {
                    // Starving a block breaks the arc — usually integration or personal leadership.
                    coverageDelta -= 8; accredDelta -= 6; coachKey = `coach_r2_starved`;
                } else if (maxBlock - minBlock <= 16) {
                    // Reasonably balanced allocation across the arc.
                    coverageDelta += 10; satDelta += 4;
                } else {
                    coverageDelta += 4;
                }
                // Integration capstone is the only place several outcomes are demonstrated together.
                if (it >= 24) { accredDelta += 6; coverageDelta += 4; }
                else if (it <= 8) { accredDelta -= 5; }
                // Foundations must be substantive to support what follows.
                if (fo >= 16 && fo <= 32) { coverageDelta += 3; }

                // Sequence the arc (Common Error: playlist, not arc).
                switch (d.sequence) {
                    case `arc`: coverageDelta += 8; satDelta += 8; accredDelta += 4; coachKey = (coachKey === `coach_r2_starved`) ? coachKey : `coach_r2_arc`; break;
                    case `frontload`: satDelta -= 8; coverageDelta -= 4; coachKey = `coach_r2_frontload`; break;
                    case `playlist`: satDelta -= 6; coverageDelta -= 3; coachKey = `coach_r2_playlist`; break;
                    case `finance`: satDelta -= 4; coverageDelta -= 2; break;
                }

                // Spacing across the 4-month window supports transfer.
                switch (d.spacing) {
                    case `spaced`: satDelta += 5; accredDelta += 2; break;
                    case `massed`: satDelta -= 3; break;
                    case `none`: satDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r2_nospacing` : coachKey; break;
                }

                summaryKey = (d.sequence === `arc` && minBlock > 8 && it >= 24) ? `sum_r2_good` :
                             ((d.sequence === `playlist` || d.sequence === `frontload`) ? `sum_r2_playlist` : `sum_r2_weak`);
            } else if (round === 3) {
                // Faculty-vs-practitioner mix + assessment design (Common Errors: star overload; practitioner default; taught-not-assessed).
                const m = d.mix / 100;   // share of days led by core faculty

                // Qualified-faculty coverage: too few faculty hollows accreditation & raises satisfaction variance;
                // a healthy footprint is ~50-70% faculty days given only 9 of 28 are free.
                if (m < 0.4) {
                    accredDelta -= 8; satDelta -= 6; coachKey = `coach_r3_practitioner`;
                } else if (m >= 0.4 && m <= 0.7) {
                    accredDelta += 8; satDelta += 4;
                } else {
                    // Over 70% faculty days on a 9-person roster strains utilization.
                    accredDelta += 4; utilDelta -= 6;
                }

                // Star-faculty overload vs balanced spread (utilization sustainability).
                switch (d.star) {
                    case `balanced`: utilDelta += 12; satDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_balanced` : coachKey; break;
                    case `overload`: utilDelta -= 14; satDelta += 3; ds.overloaded = true; coachKey = `coach_r3_overload`; break;
                    case `rotate`: utilDelta += 6; satDelta -= 6; accredDelta -= 3; coachKey = `coach_r3_rotate`; break;
                }

                // Assessment design — the heart of assurance of learning (taught vs assessed).
                switch (d.assess) {
                    case `prepost`: accredDelta += 14; coverageDelta += 8; coachKey = `coach_r3_prepost`; break;
                    case `project`: accredDelta += 4; coverageDelta += 2; break;
                    case `attendance`: accredDelta -= 12; coverageDelta -= 8; ds.taughtNotAssessed = true; coachKey = `coach_r3_attendance`; break;
                    case `taught`: accredDelta -= 14; coverageDelta -= 10; ds.taughtNotAssessed = true; coachKey = `coach_r3_taught`; break;
                }

                // How many of the six outcomes get a dedicated graded instrument drives coverage directly.
                const assessedShare = d.assessed / this.OUTCOMES;       // 0..1
                coverageDelta += Math.round((assessedShare * 40) - 20); // 6/6 -> +20, 0/6 -> -20
                accredDelta += Math.round((assessedShare * 20) - 10);
                if (d.assessed <= 3) { ds.taughtNotAssessed = true; if (coachKey === `coach_default`) coachKey = `coach_r3_undermeasured`; }

                summaryKey = (d.assess === `prepost` && d.assessed >= 5 && d.star === `balanced` && m >= 0.4 && m <= 0.7) ? `sum_r3_good` :
                             ((d.assess === `taught` || d.assess === `attendance` || d.assessed <= 2) ? `sum_r3_unassessed` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend to the committee (Common Error: optimise the four KPIs separately).
                switch (d.pitch) {
                    case `integrated`: coverageDelta += 6; accredDelta += 10; satDelta += 4; utilDelta += 3; coachKey = `coach_r4_integrated`; break;
                    case `coverage`: coverageDelta += 4; accredDelta -= 2; coachKey = `coach_r4_singlekpi`; break;
                    case `satisfaction`: satDelta += 5; accredDelta -= 4; coachKey = `coach_r4_singlekpi`; break;
                    case `compliance`: accredDelta += 3; satDelta -= 4; coachKey = `coach_r4_singlekpi`; break;
                }

                // The chair probes the weakest link: is outcome four assessed, not just taught?
                switch (d.probe) {
                    case `instrument`: accredDelta += 14; coverageDelta += 6; if (d.pitch === `integrated`) coachKey = `coach_r4_facedown`; break;
                    case `taught`: accredDelta -= 10; coverageDelta -= 4; coachKey = `coach_r4_probetaught`; break;
                    case `survey`: accredDelta -= 8; coachKey = `coach_r4_probesurvey`; break;
                    case `defer`: accredDelta -= 12; satDelta -= 3; coachKey = `coach_r4_probedefer`; break;
                }

                // Which two KPIs to stake the contract on.
                switch (d.kpi) {
                    case `coverage_accred`: accredDelta += 6; coverageDelta += 4; break;
                    case `sat_util`: satDelta += 4; utilDelta += 4; accredDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_wrongstake` : coachKey; break;
                    case `all`: coverageDelta += 2; accredDelta += 2; satDelta += 2; utilDelta += 2; break;
                }

                if (d.conviction >= 60) { accredDelta += 5; coverageDelta += 3; }
                else if (d.conviction <= 25) { accredDelta -= 5; satDelta -= 3; }

                summaryKey = (d.pitch === `integrated` && d.probe === `instrument`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: contact-hours envelope is committed in R2.
            if (round === 2) {
                ds.hoursUsed = Math.round(hoursSpent);
                ds.overCap = ds.hoursUsed > this.HOURS_CAP;
            }

            // Apply deltas, clamped (coverage & accred start low; util & sat start mid; all 0-100).
            ds.coverage = Math.max(0, Math.min(100, Math.round(ds.coverage + coverageDelta)));
            ds.util = Math.max(0, Math.min(100, Math.round(ds.util + utilDelta)));
            ds.sat = Math.max(0, Math.min(100, Math.round(ds.sat + satDelta)));
            ds.accred = Math.max(0, Math.min(100, Math.round(ds.accred + accredDelta)));

            ds.coverageHistory.push(ds.coverage);
            ds.utilHistory.push(ds.util);
            ds.satHistory.push(ds.sat);
            ds.accredHistory.push(ds.accred);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 - persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                coverage: ds.coverage,
                coverageDelta: Math.round(coverageDelta),
                util: ds.util,
                utilDelta: Math.round(utilDelta),
                sat: ds.sat,
                satDelta: Math.round(satDelta),
                accred: ds.accred,
                accredDelta: Math.round(accredDelta),
                hoursUsed: ds.hoursUsed,
                overCap: ds.overCap,
                overloaded: ds.overloaded,
                taughtNotAssessed: ds.taughtNotAssessed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtHours(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            return lang === `es` ? `${Math.round(v)} h` : `${Math.round(v)} h`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
