                    card.classList.toggle(`curarch-coverage-high`, Number(v) >= 80);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`utilDisplay`, `domainState.util`, (v) => {
                const card = document.querySelector(`.curarch-card-util`);
                if (card) card.classList.toggle(`curarch-util-low`, Number(v) <= 30);
                return Math.round(Number(v));
            });
            uiManager.bind(`satDisplay`, `domainState.sat`, (v) => Math.round(Number(v)));
            uiManager.bind(`accredDisplay`, `domainState.accred`, (v) => {
                const card = document.querySelector(`.curarch-card-accred`);
                if (card) {
                    card.classList.toggle(`curarch-accred-low`, Number(v) <= 40);
                    card.classList.toggle(`curarch-accred-high`, Number(v) >= 75);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.hoursUsed`, (v) => {
                return self._fmtHours(Number(v)) + ` / ` + self._fmtHours(self.HOURS_CAP);
            });

            // Faculty-mix slider readout.
            const mx = document.getElementById(`mixInput`);
            const mxReadout = document.getElementById(`mixReadout`);
            if (mx && mxReadout) {
                mxReadout.textContent = mx.value;
                mx.addEventListener(`input`, function() { mxReadout.textContent = mx.value; });
            }

            // Hours-allocation live total (must hit exactly 96h).
            const allocIds = [`foundationsInput`, `applicationInput`, `integrationInput`, `personalInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.curarch-alloc-readout`);
                if (bar) bar.style.color = (total !== self.HOURS_CAP) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

