        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const coverage = Math.round(ds.coverage);
            const util = Math.round(ds.util);
            const sat = Math.round(ds.sat);
            const accred = Math.round(ds.accred);

            // Composite weights the four KPIs the committee scores, with accreditation and coverage
            // carrying the fee and the audit.
            // v1.1.0 - reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const covered = coverage >= 70;
            const sustainable = util >= 55;
            const liked = sat >= 60;
            const compliant = accred >= 65;
            const auditFail = ds.taughtNotAssessed && accred < 55;

            // v1.1.0 - tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_rejected`;
            if (covered && sustainable && liked && compliant && composite >= 75) tierKey = `grade_approved`;
            else if (compliant && covered) tierKey = `grade_conditional`;
            else if (auditFail) tierKey = `grade_auditfail`;
            else if (ds.overloaded && util < 35) tierKey = `grade_burnout`;
            else if (composite >= 55) tierKey = `grade_revision`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (covered && sustainable && liked && compliant) insights.push(window.mySimulation.t(`insight_approved`));
            else if (auditFail) insights.push(window.mySimulation.t(`insight_auditfail`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.overCap) insights.push(window.mySimulation.t(`insight_overcap`));
            if (ds.overloaded) insights.push(window.mySimulation.t(`insight_overload`));
            if (ds.taughtNotAssessed) insights.push(window.mySimulation.t(`insight_taught`));
            if (accred < 45) insights.push(window.mySimulation.t(`insight_lowaccred`));
            if (covered && compliant && sat >= 65) insights.push(window.mySimulation.t(`insight_strong`));

            return {
                coverage: coverage,
                util: util,
                sat: sat,
                accred: accred,
                covered: covered,
                sustainable: sustainable,
                liked: liked,
                compliant: compliant,
                auditFail: auditFail,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="cua-cm"><p class="cua-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="cua-cm-chip ` + (ok ? `cua-cm-ok` : `cua-cm-no`) + `">` +
                `<span class="cua-cm-ico">` + (ok ? `✓` : `✗`) + `</span>` + label + ` · ` +
