            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="cua-cm">` +
  `<div class="cua-cm-head">` +
    `<div class="cua-cm-score"><div class="cua-cm-score-num">` + Math.round(s.composite) +
