                    warn_alloc_negative:    `Hour allocations cannot be negative.`,
                    warn_hours_total:       `The four blocks must total exactly 96 hours — the contact-hours envelope is fixed. Re-balance.`,
                    warn_mix_range:         `The faculty-day share must be a percentage between 0 and 100.`,
